const msg = $json.message;
if (!msg) return [];
if (msg.from?.is_bot) return []; // CRÍTICO: ignorar los mensajes del propio bot (evita bucles de confirmaciones)
const GRUPOS = {
  '-5363971034': 'PAGOS',
  '-5154074469': 'LOGISTICA',
  '-5559621779': 'CONTABILIDAD'
};
const chat = String(msg.chat?.id || '');
const grupo = GRUPOS[chat] || 'DESCONOCIDO';
if (grupo === 'DESCONOCIDO') return [];
const foto = msg.photo && msg.photo.length ? msg.photo[msg.photo.length - 1] : null;
const docu = msg.document || null;
const media = foto || docu;
const texto = msg.text || msg.caption || '';
const t = texto.toUpperCase();
// ===== Detección de SOLICITUD (solo grupo LOGISTICA) por MARCADORES ESTRUCTURALES =====
// El lenguaje real es variado: "hacer anticipo", "abonar", "consignar"... Los verbos no bastan.
// Contamos marcadores del formato de solicitud; con 2+ es solicitud, o con 1 + verbo de pago.
let esSolicitud = false;
if (grupo === 'LOGISTICA' && !media) {
  const marcadores = [/CUENTA DE COBRO/, /REMISI[OÓ]N/, /C\.?C\.?\s*\d|C[EÉ]DULA/, /COSTO\s*[=:]?\s*[\d.]/, /TEL[EÉ]FONO|CEL\b/, /NEQUI|DAVIPLATA|BANCOLOMBIA|DAVIVIENDA|AHORRO|CORRIENTE/]
    .filter(rx => rx.test(t)).length;
  const verbo = /PAG(O|AR)|ANTICIPO|ABON(O|AR)|CONSIGN|TRANSFER|GIR(O|AR)/.test(t);
  esSolicitud = marcadores >= 2 || (marcadores >= 1 && verbo);
}
// ===== Referencia de ID (Pagos y Contabilidad): la REMISIÓN también es el ID de la compra =====
let idCompraRef = null;
if (!media && !esSolicitud && grupo !== 'LOGISTICA') {
  const m = t.match(/\b(?:ID|COMPRA|COTIZACION|COTIZACIÓN|OC|REMISION|REMISIÓN)\s*[:#=.]?\s*(\d{4,6})\b/) || t.match(/^\s*(\d{4,6})\s*$/);
  if (m) idCompraRef = parseInt(m[1]);
}
const mime = docu ? (docu.mime_type || 'application/octet-stream') : (foto ? 'image/jpeg' : null);
return [{ json: {
  ruta: media ? 'COMPROBANTE' : (esSolicitud ? 'SOLICITUD_TRANSPORTE' : (idCompraRef ? 'REFERENCIA_ID' : 'IGNORAR')),
  grupo,
  id_compra_ref: idCompraRef,
  mes: new Date(msg.date * 1000).toISOString().slice(0, 7),
  wa_from: String(msg.from?.id || ''),
  wa_name: [msg.from?.first_name, msg.from?.last_name].filter(Boolean).join(' ') || (msg.from?.username || ''),
  wa_msg_id: String(msg.message_id),
  wa_timestamp: new Date(msg.date * 1000).toISOString(),
  texto,
  file_id: media ? media.file_id : null,
  mime_type: mime,
  filename: (docu && docu.file_name) ? docu.file_name : (media ? 'comprobante_' + msg.message_id + (mime === 'application/pdf' ? '.pdf' : '.jpg') : null)
}}];

// Si la carpeta AAAA-MM existe, usar su id; si no, señal para crearla
const items = $input.all().filter(i => i.json && i.json.id);
if (items.length > 0) return [{ json: { carpeta_id: items[0].json.id, crear: false } }];
return [{ json: { crear: true, mes: $('Clasificar mensaje (grupo + contenido)').first().json.mes } }];

// El binario viene del nodo de descarga (rama directa)
const b64 = Buffer.from(await this.helpers.getBinaryDataBuffer(0, 'data')).toString('base64');
let mime = $('Clasificar mensaje (grupo + contenido)').first().json.mime_type || 'image/jpeg';
if (!['image/jpeg','image/png','image/gif','image/webp','application/pdf'].includes(mime)) mime = 'image/jpeg';
const isPdf = mime === 'application/pdf';
const grupo = $('Clasificar mensaje (grupo + contenido)').first().json.grupo;
const block = isPdf
  ? { type: 'document', source: { type: 'base64', media_type: 'application/pdf', data: b64 } }
  : { type: 'image', source: { type: 'base64', media_type: mime, data: b64 } };
const prompt = `Eres el sistema OCR contable de MeUp (Colombia). Este documento llegó al grupo interno "${grupo}" (PAGOS = abonos de clientes a MeUp; LOGISTICA = pagos de MeUp a transportistas; CONTABILIDAD = egresos, gastos, facturas de compra y órdenes de compra de MeUp). Analiza y responde SOLO con JSON válido, sin markdown:
{
 "tipo_documento": "COMPROBANTE_TRANSFERENCIA|ORDEN_COMPRA|FACTURA|OTRO",
 "clasificacion": "COMPROBANTE_PAGO|FACTURA|EXTRACTO|OTRO",
 "fecha_pago": "YYYY-MM-DD o null",
 "valor": numero o null,
 "moneda": "COP|USD",
 "banco_origen": "string o null",
 "banco_destino": "string o null",
 "medio": "NEQUI|DAVIPLATA|BANCOLOMBIA|PSE|OTRO",
 "referencia": "string o null",
 "nombre_pagador": "string o null",
 "nombre_destinatario": "string o null",
 "telefono_destino": "string o null",
 "destino_es_meup": true|false|null,
 "origen_es_meup": true|false|null,
 "oc_numero": "string o null (número de orden de compra / pedido, suele coincidir con el ID de Symphony)",
 "categoria_gasto": "ARRIENDO|NOMINA|VIATICOS|IMPUESTOS|SERVICIOS|TRANSPORTE|IMPORTACION|GIRO_INTERNACIONAL|COMPRA_PROVEEDOR|GASTO_GENERAL|null",
 "confianza": "ALTA|MEDIA|BAJA",
 "observaciones": "string"
}
IDENTIFICADORES DE MEUP: nombre contiene MEUP o ME UP; NIT 900570024; cuentas Bancolombia corriente 3762, Bancolombia ahorros 8985, Davivienda ahorros 4335, Davivienda corriente 6614, Banco Agrario 9030, Bancolombia Panamá 3826.
REGLAS: destino_es_meup=true si el beneficiario es MeUp. Un cliente pagando a MeUp muestra dinero saliendo de SU cuenta hacia MeUp: destino_es_meup=true. punto = separador de miles (700.000 = 700000). categoria_gasto solo aplica a egresos de MeUp; para pagos de clientes déjala null. Si el documento es una ORDEN DE COMPRA (pedido a proveedor, sin transferencia), tipo_documento=ORDEN_COMPRA y extrae oc_numero y nombre del proveedor en nombre_destinatario.`;
return [{ json: { anthropic_body: {
  model: 'claude-sonnet-4-6', max_tokens: 1024,
  messages: [{ role: 'user', content: [ block, { type: 'text', text: prompt } ] }]
}}}];

let p = { clasificacion: 'OTRO', tipo_documento: 'OTRO', confianza: 'BAJA', observaciones: 'Error de parseo OCR' };
try {
  const raw = $json.content.filter(b => b.type === 'text').map(b => b.text).join('');
  p = JSON.parse(raw.replace(/```json|```/g, '').trim());
} catch (e) {}
const meta = $('Clasificar mensaje (grupo + contenido)').first().json;
let drive = {};
try { drive = $('Subir a Google Drive').first().json || {}; } catch (e) { /* la subida a Drive falló o no corrió: registrar igual */ }
const cap = (meta.texto || '').toUpperCase();
// ===== Clasificación: el GRUPO manda; el flujo de dinero afina =====
let clasif;
if (p.tipo_documento === 'ORDEN_COMPRA') {
  clasif = 'ORDEN_COMPRA';
} else if (meta.grupo === 'PAGOS') {
  // En Pagos solo llegan abonos de clientes; el OCR solo puede corregir si es clarísimo que MeUp es el pagador
  clasif = (p.origen_es_meup === true && p.destino_es_meup !== true) ? 'COMPROBANTE_EGRESO' : 'COMPROBANTE_PAGO';
} else if (meta.grupo === 'LOGISTICA') {
  clasif = 'COMPROBANTE_EGRESO';
} else { // CONTABILIDAD: aquí no llegan pagos de clientes
  clasif = (p.destino_es_meup === true) ? 'COMPROBANTE_PAGO' : 'COMPROBANTE_EGRESO';
}
const esEgreso = clasif === 'COMPROBANTE_EGRESO';
const estado = clasif === 'ORDEN_COMPRA' ? 'ARCHIVO' : ((p.clasificacion === 'COMPROBANTE_PAGO' || p.tipo_documento === 'COMPROBANTE_TRANSFERENCIA') ? 'PROCESADO' : 'REVISAR');
return [{ json: {
  ID_DOC: 'WA-' + Date.now().toString().slice(-9),
  FECHA_RECIBIDO: meta.wa_timestamp.replace('T',' ').slice(0,16),
  REMITENTE_WA: 'tg:' + meta.wa_from,
  NOMBRE_CONTACTO: meta.wa_name,
  TIPO_ARCHIVO: meta.mime_type,
  URL_DRIVE: drive.webViewLink || (drive.id ? 'https://drive.google.com/file/d/' + drive.id : 'SIN_URL_REVISAR'),
  OCR_ESTADO: p.confianza === 'BAJA' ? 'REVISAR' : 'OK',
  OCR_FECHA_PAGO: p.fecha_pago || '',
  OCR_VALOR: p.valor || '',
  OCR_BANCO_ORIGEN: p.banco_origen || '',
  OCR_BANCO_DESTINO: (p.banco_destino || p.medio || ''),
  OCR_REFERENCIA: [p.referencia, p.telefono_destino].filter(Boolean).join(' | '),
  OCR_CLIENTE: esEgreso || clasif === 'ORDEN_COMPRA' ? (p.nombre_destinatario || '') : (p.nombre_pagador || ''),
  OCR_CONFIANZA: p.confianza,
  CLASIFICACION: clasif,
  ID_MOV_MATCH: '',
  ESTADO: estado,
  RECIBO_SIIGO: '',
  NOTAS: (p.observaciones || '') + (meta.texto ? ' | Caption: ' + meta.texto : ''),
  HUMAN_REVIEW: 'PENDIENTE',
  ID_COMPRA_INFORMADO: (function(){
    if (p.oc_numero) return String(p.oc_numero).replace(/\D/g,'');
    const m = (meta.texto || '').toUpperCase().match(/\b(?:ID|COMPRA|COTIZACION|COTIZACIÓN|OC|REMISION|REMISIÓN)\s*[:#=.]?\s*(\d{4,6})\b/);
    return m ? m[1] : '';
  })(),
  GRUPO_ORIGEN: meta.grupo,
  CATEGORIA_GASTO: esEgreso || clasif === 'ORDEN_COMPRA' ? (p.categoria_gasto || (meta.grupo === 'LOGISTICA' ? 'TRANSPORTE' : '')) : '',
  OC_NUM: p.oc_numero || ''
}}];

const meta = $('Clasificar mensaje (grupo + contenido)').first().json;
const filas = $('Leer comprobantes recientes').all().map(i => i.json);
const remitente = 'tg:' + meta.wa_from;
const ahora = new Date(meta.wa_timestamp).getTime();
const candidatas = filas
  .filter(f => f.REMITENTE_WA === remitente && f.FECHA_RECIBIDO && f.GRUPO_ORIGEN === meta.grupo)
  .map(f => ({ f, ts: new Date(String(f.FECHA_RECIBIDO).replace(' ', 'T')).getTime() }))
  .filter(x => !isNaN(x.ts) && (ahora - x.ts) >= 0 && (ahora - x.ts) <= 60 * 60 * 1000)
  .sort((a, b) => b.ts - a.ts);
if (candidatas.length === 0) {
  return [{ json: { encontrado: false, id_compra: meta.id_compra_ref, aviso: 'Llegó la referencia ' + meta.id_compra_ref + ' pero no hay comprobante de ' + (meta.wa_name || remitente) + ' en la última hora en este grupo.' } }];
}
const c = candidatas[0].f;
return [{ json: { encontrado: true, ID_DOC: c.ID_DOC, id_compra: meta.id_compra_ref,
  notas_nuevas: ((c.NOTAS || '') + ' | ID informada por asesor: ' + meta.id_compra_ref).slice(0, 500) } }];

// Junta el ARCHIVO (binario de la descarga de Telegram) con la CARPETA del mes resuelta/creada
const bin = $('Descargar archivo (Telegram getFile)').first().binary;
if (!bin || !bin.data) throw new Error('No llegó el binario desde la descarga de Telegram');
const folderId = $json.carpeta_id || $json.id;
if (!folderId) throw new Error('No se resolvió la carpeta del mes');
return [{ json: { folder_id: folderId }, binary: bin }];

// El MISMO soporte llega a dos grupos (ej: pago a transportista → Logística Y Contabilidad).
// Si ya existe un comprobante con la misma referencia bancaria (o valor+fecha+beneficiario),
// la nueva llegada se archiva como COPIA_SOPORTE: se guarda en Drive y en el Sheet, pero
// ningún motor (WF-02/08/10) la procesa — evita cruces dobles y falsas alarmas de duplicado.
const fila = { ...$('Parsear resultado OCR').first().json };
let existentes = [];
try { existentes = $('Leer comprobantes (antiduplicado)').all().map(i => i.json).filter(f => f.ID_DOC); } catch (e) {}
const norm = s => String(s || '').toUpperCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '').trim();
const refNueva = norm(fila.OCR_REFERENCIA);
const dup = existentes.find(f => {
  if (f.ID_DOC === fila.ID_DOC) return false;
  // Coincidencia fuerte: misma referencia bancaria (no vacía, >5 caracteres)
  if (refNueva && refNueva.length > 5 && norm(f.OCR_REFERENCIA) === refNueva) return true;
  // Coincidencia por valor + fecha + beneficiario/cliente
  const mismoValor = String(f.OCR_VALOR) === String(fila.OCR_VALOR) && fila.OCR_VALOR;
  const mismaFecha = f.OCR_FECHA_PAGO && f.OCR_FECHA_PAGO === fila.OCR_FECHA_PAGO;
  const mismoNombre = norm(f.OCR_CLIENTE) && norm(f.OCR_CLIENTE) === norm(fila.OCR_CLIENTE);
  return mismoValor && mismaFecha && mismoNombre;
});
if (dup) {
  fila.ESTADO = 'COPIA_SOPORTE';
  fila.ID_MOV_MATCH = dup.ID_MOV_MATCH || '';
  fila.NOTAS = ('Copia del soporte ' + dup.ID_DOC + ' (' + (dup.GRUPO_ORIGEN || '?') + ') | ' + (fila.NOTAS || '')).slice(0, 500);
  fila.es_copia = true; fila.original = dup.ID_DOC;
}
return [{ json: fila }];
